import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const primaryVariant = "bg-[#26453f] text-white hover:bg-[#1f3631]"
const secondaryVariant = "bg-[#f1f1f1] text-[#111111] hover:bg-[#e6e6e6]"
const outlinePrimaryVariant =
  "border border-[#26453f] bg-white text-[#26453f] hover:bg-[#e5f1ee]"
const outlineNeutralVariant =
  "border border-[#e6e6e6] bg-white text-[#111111] hover:bg-[#f5f5f5]"
const ghostVariant = "bg-transparent text-[#111111] hover:bg-[#f1f1f1]"
const destructiveVariant = "bg-[#e73f3f] text-white hover:bg-[#cf2f2f]"
const linkVariant = "text-[#26453f] underline-offset-4 hover:underline"

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-[8px] font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#111111] focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 aria-disabled:pointer-events-none aria-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: primaryVariant,
        primary: primaryVariant,
        secondary: secondaryVariant,
        "outline-primary": outlinePrimaryVariant,
        "outline-neutral": outlineNeutralVariant,
        outline: outlineNeutralVariant,
        ghost: ghostVariant,
        destructive: destructiveVariant,
        link: linkVariant,
      },
      size: {
        default: "h-10 px-4 text-[14px] leading-[20px] [&_svg]:size-4",
        lg: "h-11 px-5 text-[14px] leading-[20px] [&_svg]:size-5",
        sm: "h-8 px-3 text-[12px] leading-[16px] [&_svg]:size-3.5",
        mini: "h-7 px-2 text-[12px] leading-[16px] [&_svg]:size-3",
        icon: "h-10 w-10 p-0 [&_svg]:size-4",
        "icon-lg": "h-11 w-11 p-0 [&_svg]:size-5",
        "icon-sm": "h-8 w-8 p-0 [&_svg]:size-3.5",
        "icon-mini": "h-7 w-7 p-0 [&_svg]:size-3",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button"
    return (
      <Comp
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    )
  }
)
Button.displayName = "Button"

export { Button, buttonVariants }
